def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=3 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<R and 0<=xx<C and g[yy][xx]==3 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append(comp)
    if comps:
        for y,x in max(comps,key=len): g[y][x]=7
    return g
